/**
 * The Deep Dive screen's own, more prominent banner -- distinct from the compact [DeepDiveLabel]
 * used on the preview card and atop [DeepDiveCard]. This is the one place the authoritative
 * `deep_analysis_date` (with year, since nothing else on this dedicated screen already establishes
 * the year) and `next_deep_dive_trigger_reason` ("biweekly"/"earnings", free-form per the backend
 * -- same treatment as `technicalSetup` elsewhere in this app, not a fixed enum) are both shown
 * together. Same cold-start rule as [deepDiveDisplayText]: both dates null renders nothing.
 */
@Composable
fun DeepDiveHeaderBanner(
    deepAnalysisDate: String?,
    nextDeepDiveTriggerDate: String?,
    nextDeepDiveTriggerReason: String?,
    modifier: Modifier = Modifier
) {
    if (deepAnalysisDate == null && nextDeepDiveTriggerDate == null) return
    val pulseColors = LocalPulseColors.current

    val datedPart = deepAnalysisDate?.let {
        stringResource(id = R.string.stock_detail_deep_dive_dated, it.toShortDateWithYearString())
    }
    val nextPart = nextDeepDiveTriggerDate?.let {
        val nextRes = if (deepAnalysisDate == null) R.string.stock_detail_deep_dive_next_standalone else R.string.stock_detail_deep_dive_next
        stringResource(id = nextRes, it.toShortDateString())
    }
    val text = listOfNotNull(datedPart, nextPart).joinToString(" · ") +
        (nextDeepDiveTriggerReason?.let { " ($it)" } ?: "")

    Surface(
        modifier = modifier.fillMaxWidth(),
        color = pulseColors.accentSurfaceStrong,
        shape = RoundedCornerShape(dimensionResource(id = R.dimen.corner_radius_pill))
    ) {
        Row(
            modifier = Modifier.padding(
                horizontal = dimensionResource(id = R.dimen.padding_large),
                vertical = dimensionResource(id = R.dimen.padding_medium)
            ),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(
                painter = painterResource(id = R.drawable.ic_ai_sparkle_filled),
                contentDescription = stringResource(id = R.string.stock_analysis_ai_glyph_content_description),
                tint = pulseColors.accentPrimary,
                modifier = Modifier.size(dimensionResource(id = R.dimen.icon_size_small))
            )
            Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_small)))
            Text(
                text = text.uppercase(Locale.US),
                style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                color = pulseColors.accentPrimary
            )
        }
    }
}

